// swift-tools-version:5.9
//
// Distribution package for AgentforceSDK + AgentforceVoice + AgentforceCustomization
// — generated by the Agentforce release scripts from each component's
// scripts/build-xcframework.sh output. Wrapper-pattern: each public library
// product is implemented by a wrapper target that carries a binary XCFramework
// plus its SPM-resolved transitive dependencies.
//
// All three products ship from the same public SDK repo/release. AgentforceService
// is a shared BINARY dependency and is declared once. AgentforceCustomization is a
// binary-on-binary consumer of AgentforceSDK (which is itself binary-on-binary on
// AgentforceService) — its wrapper target depends on the SDK + Service binaries
// plus MobileCustomizationFramework. The LiveKitWebRTC / RustLiveKitUniFFI binary
// targets are spliced verbatim from the AgentforceVoice build output.
//
// Do not hand-edit: regenerated on every SPM release.

import PackageDescription

let package = Package(
    name: "AgentforceSDK",
    defaultLocalization: "en",
    platforms: [
        .iOS(.v17)
    ],
    products: [
        .library(
            name: "AgentforceSDK",
            targets: ["AgentforceSDKTarget"]
        ),
        .library(
            name: "AgentforceVoice",
            targets: ["AgentforceVoiceTarget"]
        ),
        .library(
            name: "AgentforceCustomization",
            targets: ["AgentforceCustomizationTarget"]
        )
    ],
    dependencies: [
        .package(url: "https://github.com/forcedotcom/SalesforceMobileInterfaces-iOS", from: "1.0.0"),
        .package(url: "https://github.com/Salesforce-Async-Messaging/SMIClientCore-iOS.swift.git", from: "1.11.0"),
        .package(url: "https://github.com/salesforce/SharedUI-iOS", .upToNextMajor(from: "1.3.1")),
        // MobileCustomizationFramework is net-new for AgentforceCustomization.
        // Pinned exact to the version the Customization XCFramework was built
        // against (its binary .swiftinterface verifies against MCF 6.4.5's API).
        .package(url: "https://github.com/salesforce/MobileCustomizationFramework-iOS.git", exact: "6.4.5"),
    ],
    targets: [
        .binaryTarget(
            name: "AgentforceSDK",
            path: "AgentforceSDK.xcframework"
        ),
        .binaryTarget(
            name: "AgentforceVoice",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-rc1/AgentforceMobileVoice-262-2-RC1-spm.xcframework.zip",
            checksum: "7c2429f1245db6addf3635aa87bbe5c50e405526fde45f93dc54c1dde810c2b8"
        ),
        .binaryTarget(
            name: "AgentforceService",
            url: "https://github.com/forcedotcom/AgentforceMobileService-iOS/releases/download/6.11.5-rc1/AgentforceMobileService-262-2-RC1-spm.xcframework.zip",
            checksum: "f7e6ab616c7b3aa4bffeb6c0b9c5c6954666166d559b86c1c10c79901f2beedd"
        ),
        .binaryTarget(
            name: "AgentforceCustomization",
            url: "https://github.com/salesforce/AgentforceMobileSDK-iOS/releases/download/18.33.14-rc1/AgentforceMobileCustomization-262-2-RC1-spm.xcframework.zip",
            checksum: "721d06f06828e98ac21b4bc1724b7ca4ee43c24048cb3f3e3c3c3f3fc10d412d"
        ),
        .binaryTarget(
            name: "LiveKitWebRTC",
            url: "https://github.com/livekit/webrtc-xcframework/releases/download/137.7151.10/LiveKitWebRTC.xcframework.zip",
            checksum: "fdca78abe7f147bc98f60980245838471688600e0ef178a9463cd09da7fab4c8"
        ),
        .binaryTarget(
            name: "RustLiveKitUniFFI",
            url: "https://github.com/livekit/livekit-uniffi-xcframework/releases/download/0.0.3/RustLiveKitUniFFI.xcframework.zip",
            checksum: "c21c932fc91a44c34f0b6aa896a91fdcbc1e55927974ad15b8cdc5115b95ec3d"
        ),
        .target(
            name: "AgentforceSDKTarget",
            dependencies: [
                "AgentforceSDK",
                "AgentforceService",
                // swift-markdown-ui intentionally omitted (SDK imports it as
                // @_implementationOnly; statically linked into the binary).
                .product(name: "SalesforceLogging",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNetwork",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser",       package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore",        package: "SMIClientCore-iOS.swift"),
                .product(name: "SharedUI", package: "SharedUI-iOS"),
            ],
            path: "Sources/AgentforceSDKTarget"
        ),
        .target(
            name: "AgentforceVoiceTarget",
            dependencies: [
                "AgentforceVoice",
                "AgentforceService",
                "LiveKitWebRTC",
                "RustLiveKitUniFFI",
                // LiveKit itself is @_implementationOnly (statically merged).
                .product(name: "SalesforceNetwork", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceLogging", package: "SalesforceMobileInterfaces-iOS"),
                // Surfaced transitively through the AgentforceService binary the
                // Voice XCFramework re-exports; SwiftPM's binary scan warns
                // unless the wrapper declares them explicitly.
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore", package: "SMIClientCore-iOS.swift"),
            ],
            path: "Sources/AgentforceVoiceTarget"
        ),
        .target(
            name: "AgentforceCustomizationTarget",
            dependencies: [
                "AgentforceCustomization",
                // Binary-on-binary: Customization calls AgentforceSDK API through
                // resilient dispatch thunks that only exist because the SDK is a
                // binary (which in turn resolves AgentforceService as a binary).
                "AgentforceSDK",
                "AgentforceService",
                .product(name: "MobileCustomizationFramework", package: "MobileCustomizationFramework-iOS"),
                .product(name: "SharedUI", package: "SharedUI-iOS"),
                // The AgentforceSDK + MobileCustomizationFramework binary
                // .swiftinterface files import these; declare them so the
                // Customization binary interface verifies. MCF adds SalesforceCache.
                .product(name: "SalesforceLogging",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNavigation", package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceNetwork",    package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceUser",       package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SalesforceCache",      package: "SalesforceMobileInterfaces-iOS"),
                .product(name: "SMIClientCore",        package: "SMIClientCore-iOS.swift"),
            ],
            path: "Sources/AgentforceCustomizationTarget"
        )
    ]
)
